import sys
from math import gcd
lo, hi = int(sys.argv[1]), int(sys.argv[2])
out = []
for N in range(lo, hi + 1):
    cands = []
    for k in range(1, N + 1):
        if N % k: continue
        m = N // k
        if m < 2 and k != 1: continue
        seen_sub = set()
        for r in range(1, m):
            if gcd(r, m) != 1: continue
            # r^k == 1 mod m
            if pow(r, k, m) != 1 % m: continue
            # cyclic subgroup of units generated by r, to reduce duplicates
            sub = frozenset(pow(r, t, m) for t in range(1, m + 1) if True) if m > 1 else frozenset()
            sub = frozenset(x for x in (pow(r, t, m) for t in range(0, m)))
            if sub in seen_sub: continue
            seen_sub.add(sub)
            if r == 1: continue
            cands.append((m, k, r))
    out.append((N, cands))
    print(N, len(cands), [f"{m}:{k}:{r}" for m, k, r in cands][:12])
